package org.xingmu.tv;
import org.json.*;import java.util.*;import java.io.*;
/** Import TVBox data, never loading executable spider/parse definitions. */
public final class TvBoxConfig {
 public static final class Site{public final String key,name,api;Site(String k,String n,String a){key=k;name=n;api=a;}}
 public final List<Site> sites=new ArrayList<>();public final List<String> liveUrls=new ArrayList<>();public final List<String> issues=new ArrayList<>();public final List<JSONObject> inline=new ArrayList<>();public int unsupported;
 public static boolean recognises(String text){try{JSONObject root=new JSONObject(text);return root.has("sites")||root.has("lives")||root.has("spider");}catch(Exception e){return false;}}
 public static TvBoxConfig parse(String text,String base)throws IOException{if(text.length()>1_000_000)throw new IOException("配置超过 1 MB");TvBoxConfig config=new TvBoxConfig();try{JSONObject root=new JSONObject(text);JSONArray sites=root.optJSONArray("sites");if(sites!=null){if(sites.length()>1000)throw new IOException("配置站点过多");Set<String> seen=new HashSet<>();for(int n=0;n<sites.length();n++){JSONObject s=sites.getJSONObject(n);String api=s.optString("api").trim();if(s.optInt("type",-1)==1&&CatalogParser.safeMediaUrl(api)){if(config.sites.size()>=50)throw new IOException("最多支持 50 个标准 API");if(seen.add(api))config.sites.add(new Site(s.optString("key","site"+n),s.optString("name","影视源 "+(n+1)),api));}else config.unsupported++;}}
 JSONArray lives=root.optJSONArray("lives");if(lives!=null)for(int n=0;n<lives.length();n++){JSONObject live=lives.getJSONObject(n);String url=resolve(live.optString("url"),base);if(!url.isEmpty()){if(CatalogParser.safeMediaUrl(url)){if(!config.liveUrls.contains(url)&&config.liveUrls.size()<30)config.liveUrls.add(url);}else config.issues.add(live.optString("name","直播源")+"：地址格式不支持");}JSONArray channels=live.optJSONArray("channels");if(channels!=null)for(int j=0;j<channels.length();j++){JSONObject c=channels.getJSONObject(j);JSONArray urls=c.optJSONArray("urls");if(urls==null)continue;JSONArray valid=new JSONArray();for(int k=0;k<urls.length();k++){String address=resolve(urls.getString(k),base);if(CatalogParser.safeMediaUrl(address)&&valid.length()<8)valid.put(address);else config.issues.add(c.optString("name","频道")+"：插件或代理地址不支持");}if(valid.length()>0){JSONObject item=new JSONObject().put("id","tvbox_live_"+n+"_"+j).put("title",c.optString("name","自定义频道")).put("section","domestic").put("category",live.optString("group","其他")).put("country","未分类").put("url",valid.getString(0)).put("license","用户提供媒体").put("source","TVBox 直接直播");JSONArray backups=new JSONArray();for(int k=1;k<valid.length();k++)backups.put(valid.getString(k));item.put("backupUrls",backups);config.inline.add(item);}}}
 return config;
 }catch(JSONException e){throw new IOException("TVBox 配置格式错误",e);}}
 private static String resolve(String value,String base){value=value.trim();if(value.isEmpty())return "";if(CatalogParser.safeMediaUrl(value)||base==null||base.isEmpty())return value;try{return new java.net.URI(base).resolve(value).toString();}catch(Exception e){return value;}}
}
